ROW.COLUMN:
--FR_EmployeeATMOnline_ONLINE_EmpIP ------------------- --Access Event SELECT E.EMP_INTRL_ID, E.EMP_SEQ_ID, CASE AE.MANTAS_TRXN_CHANL_CD WHEN 'ON-LINE' THEN AE.MANTAS_TRXN_CHANL_DTL_4_TX WHEN 'OTHER-ANONYMOUS' THEN AE.MANTAS_TRXN_CHANL_DTL_3_TX WHEN 'OTHER-NON-ANONYMOUS' THEN AE.MANTAS_TRXN_CHANL_DTL_5_TX END AS IP_Addr, CASE WHEN E.EMP_HIRE_DT is not null AND ((SELECT KC.CLNDR_DT FROM @MANTAS@.KDD_CAL KC WHERE KC.CLNDR_NM='SYSCAL' AND KC.CLNDR_DAY_AGE = 0) - E.EMP_HIRE_DT) < @Min_Employment_Length THEN 'NEW' ELSE 'SEASONED' END AS Emp_Type FROM
@BUSINESS@.ACCT_ACCESS_EVENT AE INNER JOIN @BUSINESS@.ACCT A ON A.ACCT_INTRL_ID = AE.ACCT_INTRL_ID INNER JOIN @BUSINESS@.NTWK_USER_ACCT_MAP NUAM ON A.ACCT_INTRL_ID = NUAM.ACCT_INTRL_ID INNER JOIN @BUSINESS@.EMP E ON E.EMP_INTRL_ID = NUAM.EMP_INTRL_ID
WHERE --Mantas Transaction Channel AE.MANTAS_TRXN_CHANL_CD in (@Mantas_Trxn_Chanl_Lst) --Employee IP Lookback AND AE.ACCESS_EVENT_DT IN (SELECT KC.CLNDR_DT FROM @MANTAS@.KDD_CAL KC WHERE KC.CLNDR_NM='SYSCAL' AND KC.CLNDR_DAY_AGE between 0 and @Emp_IP_Lookback - 1) --Included Jurisdiction Codes AND (@All_Jurisdictions_Fl = 'Y' OR E.JRSDCN_CD IN (@Incl_Jurisdictions_Lst))
